WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-PC-014', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_property_damage', 'state', 'state -- ALL_STATES', 'Property Damage -- Establishing Scope, Value, and Who Pays', 'state_court | state_regulator', 'personal_crisis_property_damage', 'https://content.naic.org/consumer.htm', 'Your state Department of Insurance -- see jurisdiction table | Your state AG consumer protection division | Local code enforcement', 'State property damage and negligence statutes of limitation | State unfair claims settlement practices acts | UCC Article 2 where goods are involved | State tort claims acts where a public entity is responsible.', 'VERIFIED', '2026-08-17', 'PHOTOGRAPH EVERYTHING BEFORE CLEANUP AND KEEP THE DAMAGED ITEMS WHERE IT IS SAFE TO DO SO. Scope disputes are decided on evidence that is routinely discarded within 48 hours of the loss. Ask your own insurer directly whether it is pursuing subrogation and whether your deductible will be recovered -- deductible reimbursement out of a subrogation recovery is a real entitlement in most states and is almost never offered without a request. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 1e146456306de42673559317c328dcaf5c6a9ed22c5c3c37aaac8d1b83d0a4bc]', 'v1.0'),
('SAIS-PC-015', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_contract_dispute', 'state', 'state -- ALL_STATES', 'Contract Dispute -- Breach, Cure Rights, and What You Can Actually Recover', 'state_court | small_claims_court', 'personal_crisis_contract_dispute', 'https://www.americanbar.org/groups/legal_services/flh-home/', 'Your state bar lawyer referral service -- see jurisdiction table | Local small claims court clerk | Dial 211 for local legal aid', 'UCC Article 2 (sales of goods) | UCC Article 2A (leases) | Restatement (Second) of Contracts | Magnuson-Moss Warranty Act (15 U.S.C. sec. 2301) where a written warranty is involved | State contract statutes of limitation.', 'VERIFIED', '2026-08-17', 'READ THE NOTICE-AND-CURE AND DISPUTE-RESOLUTION CLAUSES BEFORE TAKING ANY ACTION, INCLUDING BEFORE STOPPING PAYMENT. Terminating or withholding without following the contract''s own procedure is the fastest way to lose a case you would otherwise win. If the dollar amount is within the small claims limit, small claims court is generally faster, requires no attorney, and in most states still applies the substantive law -- including UDAP damages multipliers. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0750ac2856770c3c82e15955db414e65336a5a7e79e46d4119134ebc6bd48b4d]', 'v1.0'),
('SAIS-PC-016', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_small_claims', 'state', 'state -- ALL_STATES', 'Small Claims Court -- Filing Without a Lawyer and Actually Collecting', 'state_court', 'personal_crisis_small_claims', 'https://www.lawhelp.org/', 'Your local small claims court clerk -- see jurisdiction table for state court self-help | Dial 211 for local court navigator programs', 'State small claims statutes and court rules | State rules of civil procedure governing service | State judgment enforcement and exemption statutes | Fair Debt Collection Practices Act (15 U.S.C. sec. 1692) where a collector is the plaintiff.', 'VERIFIED', '2026-08-17', 'VERIFY THE DEFENDANT''S EXACT REGISTERED LEGAL NAME THROUGH THE SECRETARY OF STATE BEFORE FILING, AND PLAN COLLECTION BEFORE YOU FILE. A judgment against a defunct entity or a judgment-proof defendant costs the same to obtain as a collectible one. Most state court systems now publish free small claims self-help guides and many courthouses have volunteer navigators -- ask the clerk what exists locally before paying anyone. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 086f4d9cab9429a14f56faabf389294b6d7dc1521166c3e736c313048a8f6420]', 'v1.0'),
('SAIS-PC-017', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_warranty_dispute', 'federal + state', 'federal + state -- ALL_STATES', 'Warranty Dispute -- Express, Implied, and the Federal Fee-Shifting Route', 'federal_agency | state_attorney_general', 'personal_crisis_warranty_dispute', 'https://www.ftc.gov/legal-library/browse/rules/magnuson-moss-warranty-act', 'FTC Consumer Response Center: 877-382-4357 | Your state AG consumer protection division -- see jurisdiction table', 'Magnuson-Moss Warranty Act (15 U.S.C. sec. 2301 et seq.) | FTC Rules on Warranties (16 CFR Parts 700, 701, 702, 703) | UCC sec. 2-314 (merchantability), sec. 2-315 (fitness), sec. 2-316 (disclaimers), sec. 2-719 (failure of essential purpose)', 'VERIFIED', '2026-08-17', 'IF THE SELLER GAVE A WRITTEN WARRANTY OR SOLD YOU A SERVICE CONTRACT, THE IMPLIED WARRANTIES GENERALLY CANNOT BE DISCLAIMED -- an ''AS IS'' sticker does not survive a written warranty under Magnuson-Moss. Say this explicitly in the demand letter. And cite Magnuson-Moss by name because of the attorney fee-shifting: it converts an uneconomic small claim into one a consumer attorney will take on contingency. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 62b9fe2dca3ecc460c8a51c6230acf91b5fca91028bd32d00dea1a2eeed936ac]', 'v1.0'),
('SAIS-PC-018', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_utility_dispute', 'federal + state', 'federal + state -- ALL_STATES', 'Utility Dispute -- Shutoff Moratoria, Medical Certificates, and the Regulator', 'state_public_utility_commission | federal_program', 'personal_crisis_utility_dispute', 'https://www.acf.hhs.gov/ocs/programs/liheap', 'Your state Public Utility/Service Commission -- see jurisdiction table | LIHEAP National Energy Assistance Referral: 866-674-6327 | Dial 211', 'Low Income Home Energy Assistance Act (42 U.S.C. sec. 8621 et seq.) | Public Utility Regulatory Policies Act (16 U.S.C. sec. 2601 et seq.) | Communications Act sec. 254 / Lifeline (47 U.S.C. sec. 254; 47 CFR Part 54) | State public utility commission statutes and shutoff regulations.', 'VERIFIED', '2026-08-17', 'FILE THE DISPUTE BEFORE THE SHUTOFF DATE, NOT AFTER. Prevention costs nothing; restoration costs reconnection fees, a deposit, and days without service. Ask by name for: the seasonal moratorium, medical certification, a deferred payment arrangement, LIHEAP crisis funds, and any percentage-of-income plan. These are separate programs with separate applications and a utility representative will rarely enumerate them unprompted. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: de4ab2b9c8fd076c9d5aaaeab82ff8b69f201ed212d400b2722b78c7d0543630]', 'v1.0'),
('SAIS-PS-001-01', 'systemic_abuse_intelligence', 401, 'missing_persons', 'missing_persons_immediate_report', 'federal + state', 'federal + state -- ALL_STATES', 'Reporting -- The 24-Hour Waiting Period Is a Myth', 'law_enforcement | federal_agency', 'missing_persons_immediate_report', 'https://www.missingkids.org/', '911 or local law enforcement | NCMEC (under 21): 800-843-5678 | FBI field office | NamUs: namus.nij.ojp.gov', 'Suzanne''s Law / National Child Search Assistance Act (34 U.S.C. sec. 41308) -- no waiting period, 2-hour NCIC entry for persons under 21 | Missing Children''s Assistance Act (34 U.S.C. sec. 11291 et seq.) | Ashanti Alert Act (34 U.S.C. sec. 41507) | State missing persons reporting statutes.', 'VERIFIED', '2026-08-17', 'REPORT NOW -- THERE IS NO WAITING PERIOD, AND FOR ANYONE UNDER 21 FEDERAL LAW REQUIRES NCIC ENTRY WITHIN TWO HOURS. If an agency tells you to wait 24 hours, cite the National Child Search Assistance Act, ask for a supervisor, and call NCMEC at 800-843-5678. Before you leave, get the CASE NUMBER, the officer''s name, and CONFIRMATION THAT THE NCIC ENTRY WAS MADE. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-001 | pipeline: Missing Persons] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 62c9791c31e4f7865ccf1c5e6d6905a2e2e9a884a4aeb3cfb23f83409b91f4d5]', 'v1.0'),
('SAIS-PS-001-02', 'systemic_abuse_intelligence', 401, 'missing_persons', 'missing_persons_databases', 'federal', 'federal -- NATIONWIDE', 'NamUs, NCIC, and NCMEC -- The Three Systems and What Each Does', 'federal_agency | law_enforcement', 'missing_persons_databases', 'https://namus.nij.ojp.gov/', 'NamUs: namus.nij.ojp.gov | NCMEC (under 21): 800-843-5678 | Your state missing persons clearinghouse -- see jurisdiction table', 'National Missing and Unidentified Persons System (NIJ program) | National Child Search Assistance Act (34 U.S.C. sec. 41308) | Missing Children''s Assistance Act (34 U.S.C. sec. 11291 et seq.) | Justice for All Act, forensic provisions | Billy''s Law provisions on database interoperability.', 'VERIFIED', '2026-08-17', 'ENTER THE CASE IN NamUs YOURSELF -- FAMILIES CAN DO IT DIRECTLY AND IT IS FREE. It creates a public record, cross-compares nationwide against unidentified remains, and unlocks FREE forensic services including DNA analysis, odontology, and anthropology. Then confirm separately that law enforcement made the NCIC entry, and ask whether DENTAL RECORDS and FINGERPRINTS have been added. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-001 | pipeline: Missing Persons] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 8438139fa6d46a8b35eef1ba5ac0aba965e28ffc7c0f524f9f1b26dc40b8b5ce]', 'v1.0'),
('SAIS-PS-001-03', 'systemic_abuse_intelligence', 401, 'missing_persons', 'missing_persons_alert_systems', 'federal + state', 'federal + state -- ALL_STATES', 'Alert Systems -- AMBER, Silver, Ashanti, Feather, and Endangered Missing', 'law_enforcement | state_agency', 'missing_persons_alert_systems', 'https://amberalert.ojp.gov/', 'Your local law enforcement agency | Your state missing persons clearinghouse -- see jurisdiction table | NCMEC: 800-843-5678', 'AMBER Alert / PROTECT Act (34 U.S.C. sec. 20501 et seq.) | Ashanti Alert Act (34 U.S.C. sec. 41507) -- missing adults 18-64 | National Child Search Assistance Act (34 U.S.C. sec. 41308) | State Silver Alert, Feather Alert, and endangered missing advisory statutes.', 'VERIFIED', '2026-08-17', 'ASK FOR THE SPECIFIC ALERT BY NAME. Most families know only AMBER. SILVER ALERT covers older adults and people with dementia; the ASHANTI ALERT exists specifically for missing adults 18-64 who fit neither; and most states have a lower-threshold ENDANGERED MISSING ADVISORY. What drives every one of them is documented DANGER -- lead with medications needed, medical and cognitive conditions, weather exposure, and any evidence of foul play. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-001 | pipeline: Missing Persons] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 32c39de3d98cc7da9668ba7034402378c19a3774650344b5c5cb28a449846506]', 'v1.0'),
('SAIS-PS-001-04', 'systemic_abuse_intelligence', 401, 'missing_persons', 'missing_persons_evidence_preservation', 'federal', 'federal -- NATIONWIDE', 'Evidence Preservation -- Records That Expire While Families Wait', 'law_enforcement | technology_platform', 'missing_persons_evidence_preservation', 'https://namus.nij.ojp.gov/', 'Local law enforcement | FBI field office | NamUs: namus.nij.ojp.gov | Your state clearinghouse', 'Preservation of stored records (18 U.S.C. sec. 2703(f)) | Emergency disclosure to law enforcement (18 U.S.C. sec. 2702(b)(8), (c)(4)) | Stored Communications Act (18 U.S.C. sec. 2701 et seq.) | Kelsey Smith Act provisions adopted in many states requiring carrier location disclosure in emergencies.', 'VERIFIED', '2026-08-17', 'ASK LAW ENFORCEMENT TODAY TO SEND PRESERVATION LETTERS AND TO REQUEST CARRIER LOCATION DATA. Both are routine and free, both are frequently not done unless requested, and the location request is measured in hours. Meanwhile, DO NOT touch the person''s devices, room, or vehicle, and set aside a hairbrush or toothbrush UNCLEANED as a DNA reference source. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-001 | pipeline: Missing Persons] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e1bf148e5f6545969ba91cfe67258146ab7e041ad1fafe966a1ff78388897b43]', 'v1.0'),
('SAIS-PS-001-05', 'systemic_abuse_intelligence', 401, 'missing_persons', 'missing_persons_case_escalation', 'federal + state', 'federal + state -- ALL_STATES', 'Escalation -- What to Do When the Investigation Goes Quiet', 'law_enforcement | state_agency | nonprofit_organization', 'missing_persons_case_escalation', 'https://namus.nij.ojp.gov/', 'Your state missing persons clearinghouse -- see jurisdiction table | FBI field office | NCMEC (under 21): 800-843-5678 | NamUs regional program specialist', 'National Child Search Assistance Act (34 U.S.C. sec. 41308) | Missing Children''s Assistance Act (34 U.S.C. sec. 11291 et seq.) | Federal Kidnapping Act (18 U.S.C. sec. 1201) | Trafficking Victims Protection Act (22 U.S.C. sec. 7101 et seq.) | State clearinghouse statutes.', 'VERIFIED', '2026-08-17', 'CONTACT THE STATE MISSING PERSONS CLEARINGHOUSE AND THE NamUs REGIONAL SPECIALIST DIRECTLY -- both provide free case support and can move an agency that has gone quiet, and neither requires the local agency''s permission. Then verify ANNUALLY that the NCIC and NamUs entries are still active and current; records are sometimes cancelled or left stale in error. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-001 | pipeline: Missing Persons] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 99c1930b97beb3754f6b97bd66fe92b04b75860b0361cb324778509e804da5dd]', 'v1.0'),
('SAIS-PS-001-06', 'systemic_abuse_intelligence', 401, 'missing_persons', 'missing_persons_family_practical_needs', 'federal + state', 'federal + state -- ALL_STATES', 'Practical and Legal Consequences for the Family Left Behind', 'state_court | state_agency | nonprofit_organization', 'missing_persons_family_practical_needs', 'https://ovc.ojp.gov/', 'Your state bar lawyer referral service | Your state crime victim compensation program | 988 | Dial 211', 'State absentee conservatorship and protective arrangement statutes | Uniform Determination of Death and state presumption-of-death statutes | Social Security survivor benefits (42 U.S.C. sec. 402) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.)', 'VERIFIED', '2026-08-17', 'ASK A PROBATE CLERK OR LEGAL AID ABOUT AN ABSENTEE CONSERVATORSHIP -- most states have a way to manage a missing person''s accounts, property, and obligations WITHOUT declaring them dead, and almost no family is told it exists while bills and mortgages keep coming due. And when seeking counseling, ask specifically for someone experienced with AMBIGUOUS LOSS; ordinary bereavement support fits this poorly. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-001 | pipeline: Missing Persons] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d16366c8f131e8cb45ab168c130f01c50fa857c9198f88ecb79aeef722f37e53]', 'v1.0'),
('SAIS-PS-002-01', 'systemic_abuse_intelligence', 402, 'dv_shelter_safety_planning', 'dv_shelter_immediate_access', 'federal + state', 'federal + state -- ALL_STATES', 'Immediate Access -- Hotlines, Shelter, and Emergency Placement', 'federal_program | state_program | nonprofit_organization', 'dv_shelter_immediate_access', 'https://www.thehotline.org/', 'National Domestic Violence Hotline: 800-799-7233 | TTY 800-787-3224 | Text START to 88788 | StrongHearts Native Helpline: 844-762-8483 | Dial 211 | 911 for immediate danger', 'Family Violence Prevention and Services Act (42 U.S.C. sec. 10401 et seq.) | Violence Against Women Act (34 U.S.C. sec. 12291 et seq.) | VAWA confidentiality provision (34 U.S.C. sec. 12291(b)(2)) | McKinney-Vento Homeless Assistance Act (42 U.S.C. sec. 11301 et seq.)', 'VERIFIED', '2026-08-17', 'CALL 800-799-7233 EVEN IF YOU HAVE NOT DECIDED ANYTHING. It is free, confidential, anonymous if you want, and staffed around the clock. And if you are told shelter is full, ask by name for a HOTEL VOUCHER, PLACEMENT IN ANOTHER COUNTY, and RAPID RE-HOUSING -- all three exist at most programs and none of them is routinely offered unprompted. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: PS-002 | pipeline: DV Shelter and Safety Planning] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 8a9c8c3b925eccb26055366efe8029de53c06079b32f897ca0f711e10daf38df]', 'v1.0'),
('SAIS-PS-002-02', 'systemic_abuse_intelligence', 402, 'dv_shelter_safety_planning', 'dv_safety_planning', 'federal + state', 'federal + state -- ALL_STATES', 'Safety Planning -- Staying, Leaving, and the Period After', 'nonprofit_organization | state_program', 'dv_safety_planning', 'https://www.thehotline.org/plan-for-safety/', 'National DV Hotline: 800-799-7233 | Text START to 88788 | Your local DV program via the state coalition -- see jurisdiction table', 'Family Violence Prevention and Services Act (42 U.S.C. sec. 10401 et seq.) | Violence Against Women Act (34 U.S.C. sec. 12291) | VAWA confidentiality for victim service providers (34 U.S.C. sec. 12291(b)(2)) | State DV advocate privilege statutes.', 'VERIFIED', '2026-08-17', 'ASK AN ADVOCATE FOR A DANGER ASSESSMENT AND BUILD THE PLAN AROUND THE SEPARATION PERIOD, NOT AROUND THE DECISION TO LEAVE. Separation is the highest-risk window, which means a plan that ends at ''get out'' is incomplete -- and it is also why nobody should be pushed to leave before they are ready. Store the go bag OUTSIDE the home. [address_resolution: Resolve via the organization''s own local chapter or affiliate locator; input = ZIP or state.] [doc_code: PS-002 | pipeline: DV Shelter and Safety Planning] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 7bd0ee863d5b1f9f83a94c4e28e71c1730ef74550542d9ab29164a2e4c711e55]', 'v1.0'),
('SAIS-PS-002-03', 'systemic_abuse_intelligence', 402, 'dv_shelter_safety_planning', 'dv_confidentiality_and_location_privacy', 'federal + state', 'federal + state -- ALL_STATES', 'Confidentiality -- Advocate Privilege, Address Programs, and Record Suppression', 'state_agency | nonprofit_organization', 'dv_confidentiality_and_location_privacy', 'https://www.thehotline.org/', 'Your state Address Confidentiality Program (secretary of state in most states) | National DV Hotline: 800-799-7233 | Your state DV coalition -- see jurisdiction table', 'VAWA confidentiality for victim service providers (34 U.S.C. sec. 12291(b)(2)) | Family Violence Prevention and Services Act confidentiality (42 U.S.C. sec. 10406(c)(5)) | FERPA (20 U.S.C. sec. 1232g) | State address confidentiality programs | State DV advocate privilege statutes.', 'VERIFIED', '2026-08-17', 'ENROLL IN THE ADDRESS CONFIDENTIALITY PROGRAM BEFORE YOU MOVE, AND ASK FOR ADDRESS PROTECTION AT THE MOMENT YOU FILE ANY COURT CASE. Location is almost always lost through public filings, not through surveillance, and both of these are preventive measures that cannot be applied retroactively. Note also that what you tell a funded DV ADVOCATE has federal confidentiality protection that most other conversations do not. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-002 | pipeline: DV Shelter and Safety Planning] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 05f8fb5fe3a18f49282b0fc8791cc420505737e1276e84857741434baaa28c9b]', 'v1.0'),
('SAIS-PS-002-04', 'systemic_abuse_intelligence', 402, 'dv_shelter_safety_planning', 'dv_housing_rights_vawa', 'federal + state', 'federal + state -- ALL_STATES', 'Housing Rights for Survivors -- Lease Termination, Eviction Defense, and VAWA', 'federal_agency | state_agency', 'dv_housing_rights_vawa', 'https://www.hud.gov/program_offices/fair_housing_equal_opp/VAWA', 'HUD Housing Discrimination Hotline: 800-669-9777 | Your public housing authority | National DV Hotline: 800-799-7233 | Dial 211 for legal aid', 'VAWA housing protections (34 U.S.C. sec. 12491; 24 CFR Part 5 Subpart L) | HUD Form 5382 self-certification | Fair Housing Act (42 U.S.C. sec. 3601 et seq.) | State survivor lease termination and lock-change statutes | State bars on penalizing emergency service calls.', 'VERIFIED', '2026-08-17', 'SELF-CERTIFY ON HUD FORM 5382 AND ASK FOR AN EMERGENCY TRANSFER IN WRITING. In federally assisted housing you generally do not need a police report or a protective order to invoke VAWA protection, and LEASE BIFURCATION can remove the person who committed the violence without ending your tenancy. In private rentals, most states now allow early lease termination and a lock change on documented survivor status -- invoke it in writing. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-002 | pipeline: DV Shelter and Safety Planning] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d16366e35e46dac43a7e6af63dba8b068b5854cab77bea912de2194f644ce312]', 'v1.0'),
('SAIS-PS-002-05', 'systemic_abuse_intelligence', 402, 'dv_shelter_safety_planning', 'dv_economic_supports', 'federal + state', 'federal + state -- ALL_STATES', 'Economic Supports -- Compensation, Benefits, Employment Leave, and Financial Abuse', 'state_agency | federal_program', 'dv_economic_supports', 'https://ovc.ojp.gov/', 'Your state crime victim compensation program -- see jurisdiction table | Dial 211 | National DV Hotline: 800-799-7233 | Your state unemployment agency', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | TANF Family Violence Option (42 U.S.C. sec. 602(a)(7)) | Child support good cause exemption (42 U.S.C. sec. 654(29); 45 CFR 264.30) | SNAP expedited service (7 U.S.C. sec. 2020(e)(9); 7 CFR 273.2(i)) | State survivor unemployment and employment leave statutes.', 'VERIFIED', '2026-08-17', 'ASK FOR THE TANF FAMILY VIOLENCE OPTION AND THE CHILD SUPPORT GOOD CAUSE EXEMPTION BY NAME, AND APPLY FOR CRIME VICTIM COMPENSATION INCLUDING RELOCATION COSTS. These three are the most consequential economic supports in this pipeline and all three are systematically underclaimed. And when filing for unemployment, state the domestic violence reason explicitly -- most states treat it as good cause, which preserves eligibility that quitting would otherwise forfeit. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-002 | pipeline: DV Shelter and Safety Planning] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0adaa6b86c5ef0a45ef3f6eda9b07d6415c5b5d3855d8392d0ea034701381c30]', 'v1.0'),
('SAIS-PS-002-06', 'systemic_abuse_intelligence', 402, 'dv_shelter_safety_planning', 'dv_dependents_and_access_barriers', 'federal + state', 'federal + state -- ALL_STATES', 'Children, Pets, Disability, Immigration, and Barriers That Keep People Trapped', 'federal_program | state_agency', 'dv_dependents_and_access_barriers', 'https://www.thehotline.org/', 'National DV Hotline: 800-799-7233 | StrongHearts Native Helpline: 844-762-8483 | Deaf survivors: videophone services via the hotline | Dial 211', 'McKinney-Vento Homeless Assistance Act, education provisions (42 U.S.C. sec. 11431 et seq.) | ADA Titles II and III (42 U.S.C. sec. 12131, 12181) | Section 504 (29 U.S.C. sec. 794) | VAWA self-petition (8 U.S.C. sec. 1154(a)(1)(A)(iii)); U visa (sec. 1101(a)(15)(U)); T visa (sec. 1101(a)(15)(T)) | Title VI language access (42 U.S.C. sec. 2000d) | State pet protection order provisions.', 'VERIFIED', '2026-08-17', 'CONTACT THE SCHOOL DISTRICT''S HOMELESS LIAISON AND CITE McKINNEY-VENTO -- children in shelter can stay in their school of origin with transportation, or enroll immediately somewhere new WITHOUT records, residency proof, or immunization paperwork. And if pets are the reason someone cannot leave, say so to the hotline: on-site pet housing and safe-haven fostering networks exist nearly everywhere and are almost never mentioned. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: PS-002 | pipeline: DV Shelter and Safety Planning] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 96da2d1f7fef37df076a8ec6ce9b4790503c2e336b50e10bbb18bb7e17658a17]', 'v1.0'),
('SAIS-PS-003-01', 'systemic_abuse_intelligence', 403, 'stalking_harassment', 'stalking_incident_log', 'state', 'state -- ALL_STATES', 'The Stalking Log -- Course of Conduct Is the Element You Have to Prove', 'victim_advocate | law_enforcement', 'stalking_incident_log', 'https://www.stalkingawareness.org/', 'Stalking Prevention, Awareness, and Resource Center (SPARC) | National DV Hotline: 800-799-7233 | Local victim advocate via your state coalition -- see jurisdiction table', 'State stalking statutes (course-of-conduct definitions) | Interstate stalking (18 U.S.C. sec. 2261A) | Violence Against Women Act (34 U.S.C. sec. 12291) | State civil protection order statutes.', 'VERIFIED', '2026-08-17', 'START THE LOG TODAY AND BACKFILL. Stalking is a course-of-conduct offense, individual incidents look trivial in isolation, and the pattern is the case. Record what you CHANGED because of each incident -- route, job, locks, schedule -- because documented behavior change is frequently how the fear element is proven. SPARC publishes a free log built for this. [address_resolution: Resolve via the state coalition''s local program directory; input = county. NOTE: shelter and safe-site addresses are CONFIDENTIAL and are never published -- the hotline arranges intake.] [doc_code: PS-003 | pipeline: Stalking and Harassment] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: adb098ed433d98b7e1276702ac7674bc916a95d16e859213d157e1c577df96f2]', 'v1.0'),
('SAIS-PS-003-02', 'systemic_abuse_intelligence', 403, 'stalking_harassment', 'stalking_law_enforcement_reporting', 'federal + state', 'federal + state -- ALL_STATES', 'Law Enforcement Reporting -- Making the Course of Conduct Visible', 'law_enforcement', 'stalking_law_enforcement_reporting', 'https://www.stalkingawareness.org/', '911 for immediate danger | Local law enforcement non-emergency line | FBI IC3 for interstate or online conduct | National DV Hotline: 800-799-7233', 'State stalking and harassment statutes | Interstate stalking (18 U.S.C. sec. 2261A) | Interstate violation of a protection order (18 U.S.C. sec. 2262) | Crime Victims'' Rights Act (18 U.S.C. sec. 3771) | Violence Against Women Act (34 U.S.C. sec. 12291)', 'VERIFIED', '2026-08-17', 'SAY THE WORD ''STALKING'' AND LIST THE PRIOR INCIDENT NUMBERS IN EVERY NEW REPORT. Those two things convert a series of nuisance calls into a documented course of conduct and frequently change which unit handles it. Ask directly whether the reports are being LINKED -- if they are not, ask for a supervisor or a detective. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-003 | pipeline: Stalking and Harassment] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d141312d9373a4fc89cb7bc443e4b5af3a6edd10462c7c3c75f2357c84bd95bd]', 'v1.0'),
('SAIS-PS-003-03', 'systemic_abuse_intelligence', 403, 'stalking_harassment', 'stalking_evidence_preservation', 'federal', 'federal -- NATIONWIDE', 'Evidence Preservation -- Records That Vanish on Short Retention Schedules', 'law_enforcement | technology_platform', 'stalking_evidence_preservation', 'https://www.ic3.gov/', 'Local law enforcement (for preservation letters to providers) | FBI IC3 | National DV Hotline: 800-799-7233 | SPARC resources', 'Preservation of stored communications (18 U.S.C. sec. 2703(f)) | Stored Communications Act (18 U.S.C. sec. 2701 et seq.) | Interstate stalking (18 U.S.C. sec. 2261A) | State stalking and electronic surveillance statutes.', 'VERIFIED', '2026-08-17', 'ASK LAW ENFORCEMENT TO SEND PRESERVATION LETTERS TO THE PROVIDERS AND PLATFORMS BY NAME, AND SEND YOUR OWN WRITTEN REQUEST TO ANY BUSINESS OR NEIGHBOR WITH CAMERA FOOTAGE WITHIN DAYS. Video is typically gone in 7-30 days. And always SCREENSHOT BEFORE REPORTING to a platform -- removal destroys the copy you did not save. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-003 | pipeline: Stalking and Harassment] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d271f5e43400dc4fd5301e44f94809c0ab587a2c6c3b01f11036d65b76396f1d]', 'v1.0'),
('SAIS-PS-003-04', 'systemic_abuse_intelligence', 403, 'stalking_harassment', 'stalking_technology_safety', 'federal', 'federal -- NATIONWIDE', 'Technology-Facilitated Stalking -- Tracking, Accounts, and Safe Remediation', 'victim_advocate | technology_platform', 'stalking_technology_safety', 'https://www.techsafety.org/', 'National DV Hotline (tech safety advocacy): 800-799-7233 | NNEDV Safety Net resources | Local law enforcement', 'Interstate stalking, including electronic (18 U.S.C. sec. 2261A(2)) | Computer Fraud and Abuse Act (18 U.S.C. sec. 1030) | Wiretap Act (18 U.S.C. sec. 2511) | Stored Communications Act (18 U.S.C. sec. 2701) | State electronic tracking and spyware statutes.', 'VERIFIED', '2026-08-17', 'GET A TECH SAFETY ADVOCATE BEFORE YOU CHANGE ANYTHING -- reachable through 800-799-7233. Removing tracking or resetting passwords announces that you know, and that moment is associated with escalation. When you do lock down, change ACCOUNT RECOVERY SETTINGS, not just passwords, and rebuild on a device the person has never touched rather than cleaning the old one. [address_resolution: Resolve via the state coalition''s local program directory; input = county. NOTE: shelter and safe-site addresses are CONFIDENTIAL and are never published -- the hotline arranges intake.] [doc_code: PS-003 | pipeline: Stalking and Harassment] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 02cd705764de96ae6bf680be3a062070d3f6c1f233e799eea7b16dc8a307a103]', 'v1.0')
